head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > getFormattedValue]<br/>Calendar 컴포넌트의 선택 날짜를 포맷이 적용된 문자열로 반환합니다.",
    "validation" : [
        "Calendar 컴포넌트의 선택 날짜를 포맷이 적용된 문자열로 String 타입으로 반환합니다.",
        "setDateFormat() 메소드로 별도 포맷을 설정하지 않은 경우 구분자 없는 숫자 문자열을 반환합니다.",
        "calendarValueType='yearMonth' 설정 시 setDateFormat() 미호출이면 'yyyyMM' 형식의 6자리 숫자 문자열을 반환합니다.",
        "calendarValueType='yearMonthDate' 설정 시 setDateFormat() 미호출이면 'yyyyMMdd' 형식의 8자리 숫자 문자열을 반환합니다.",
        "calendarValueType='yearMonthDateHour' 설정 시 setDateFormat() 미호출이면 'yyyyMMddHH' 형식의 10자리 숫자 문자열을 반환합니다.",
        "calendarValueType='yearMonthDateTime' 설정 시 setDateFormat() 미호출이면 'yyyyMMddHHmm' 형식의 12자리 숫자 문자열을 반환합니다.",
        "calendarValueType='yearMonthDateTimeSec' 설정 시 setDateFormat() 미호출이면 'yyyyMMddHHmmSS' 형식의 14자리 숫자 문자열을 반환합니다.",
        "setDateFormat() 메소드로 설정한 포맷이 적용된 날짜 문자열을 반환합니다. (예: setDateFormat('yyyy MM-dd') 호출 후 2025년 4월 15일 선택 상태이면 '2025 04-15' 반환)",
        "마스크 문자가 아닌 일반 문자(공백, '-', '/', '년', '월', '일' 등)는 setDateFormat 인자 문자열에서 그대로 결과에 포함됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarValueType : con_calendarValueType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // calendarValueType 별 자릿수에 맞춰 초기 선택 날짜 설정 (getFormattedValue 결과 확인용)
    let valueType = target1.options.calendarValueType || 'yearMonthDate';
    let initValue = '';
    if (valueType === 'yearMonth') {
        initValue = '202504';
    } else if (valueType === 'yearMonthDate') {
        initValue = '20250415';
    } else if (valueType === 'yearMonthDateHour') {
        initValue = '2025041512';
    } else if (valueType === 'yearMonthDateTime') {
        initValue = '202504151234';
    } else if (valueType === 'yearMonthDateTimeSec') {
        initValue = '20250415123456';
    }
    if (initValue !== '') {
        target1.gotoCalendar(initValue);
    }
}



// getFormattedValue() 반환값 출력
// validation: setDateFormat 미호출 시 calendarValueType 별 기본 자릿수의 구분자 없는 숫자 문자열 반환
scwin.btn_getFormattedValue_onclick = function (e) {
    let formatted = target1.getFormattedValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[getFormattedValue() 반환] '" + formatted + "'");
};



// setDateFormat 으로 포맷 설정 후 getFormattedValue 호출 → 포맷이 적용된 문자열 반환 확인
// validation: 설정한 포맷이 적용된 날짜 문자열을 반환, 마스크 외 일반 문자는 그대로 결과에 포함
scwin.btn_setAndGetFormattedValue_onclick = function (e) {
    target1.setDateFormat(par_dateFormat.getValue());
    let formatted = target1.getFormattedValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[setDateFormat 후 getFormattedValue()] '" + formatted + "'");
};
